class Solution {
public:
    int getHeight(TreeNode* root) {
        if (!root) return -1;
        return 1 + max(getHeight(root->left), getHeight(root->right));
    }

    void fill(TreeNode* root, int r, int c, int height, vector<vector<string>>& res) {
        if (!root) return;
        res[r][c] = to_string(root->val);
        int offset = 1 << (height - r - 1);
        if (root->left)  fill(root->left,  r + 1, c - offset, height, res);
        if (root->right) fill(root->right, r + 1, c + offset, height, res);
    }

    vector<vector<string>> printTree(TreeNode* root) {
        int h = getHeight(root);
        int m = h + 1;
        int n = (1 << (h + 1)) - 1;
        vector<vector<string>> res(m, vector<string>(n, ""));
        fill(root, 0, (n - 1) / 2, h, res);
        return res;
    }
};
